// STUB: ServerNotification is the generated notification union in codex-app-server-protocol.
pub type ServerNotification = ItemCompletedNotification
	| TurnCompletedNotification
	| ConfigWarningNotification
	| DeprecationNoticeNotification
	| ThreadArchivedNotification
	| ThreadNameUpdatedNotification
	| ThreadProjectUpdatedNotification
	| ThreadRevertedNotification
	| ThreadStartedNotification
	| ThreadUnarchivedNotification

// STUB: ClientResponsePayload is the generated, source-shaped response union in
// codex-app-server-protocol. The concrete variant supplies the JSON-RPC method shape; there is no
// free-form discriminator or unrelated optional-field envelope in the Rust API.
pub type ClientResponsePayload = GetConversationSummaryResponse
	| MemoryResetResponse
	| ThreadApproveGuardianDeniedActionResponse
	| ThreadArchiveResponse
	| ThreadBackgroundTerminalsCleanResponse
	| ThreadBackgroundTerminalsListResponse
	| ThreadBackgroundTerminalsTerminateResponse
	| ThreadCompactStartResponse
	| ThreadDecrementElicitationResponse
	| ThreadForkResponse
	| ThreadIncrementElicitationResponse
	| ThreadItemsListResponse
	| ThreadListResponse
	| ThreadLoadedListResponse
	| ThreadMemoryModeSetResponse
	| ThreadMetadataUpdateResponse
	| ThreadReadResponse
	| ThreadResumeResponse
	| ThreadRevertResponse
	| ThreadSearchOccurrencesResponse
	| ThreadSearchResponse
	| ThreadSectionMoveResponse
	| ThreadSetNameResponse
	| ThreadShellCommandResponse
	| ThreadStartResponse
	| ThreadTimelineListResponse
	| ThreadTurnsListResponse
	| ThreadUnarchiveResponse
	| ThreadUnsubscribeResponse

// STUB: ClearableString is the explicit V representation of Rust's `Option<Option<String>>` generated
// fields: `has_value == false` means omitted, `clear == true` means JSON null, and otherwise
// `value` is the replacement value.
pub struct ClearableString {
pub:
	has_value bool
	clear     bool
	value     string
}

